import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{   
    static long[] pre;
    static long calc(int n,int a,int b)
    {
        return 2*pre[a]+pre[a+2*b]+3*pre[3*n-2*a-b];
    }
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
        Scanner sc=new Scanner(System.in);
        int t=sc.nextInt();
        while(t-->0)
        {
            int n=sc.nextInt();
            int m=3*n;
            long[] x=new long[m];
            for(int i=0;i<m;i++)
            {
                x[i]=sc.nextLong();
            }
            Arrays.sort(x);
            pre=new long[m+1];
            for(int i=0;i<m;i++)
            {
                pre[i+1]=pre[i]+x[m-1-i];
            }
            long ans=0;
            for(int a=0;a<=n;a++)
            {
                int l=0;
                int r=n-a;
                while(l<=r)
                {
                    int mid=(l+r)/2;
                    long curr=calc(n,a,mid);
                    long nxt=(mid<r)?calc(n,a,mid+1):Long.MIN_VALUE;
                    if(curr<=nxt)
                    {
                        l=mid+1;
                    }
                    else
                      r=mid-1;
                }
                for(int b=Math.max(0,l-2);b<=Math.min(n-a,l+2);b++)
                {
                    ans=Math.max(ans,calc(n,a,b));
                }
                
            }
            System.out.println(ans);
        }
        
	}
}
